do
    local FM = gcall(require, ReplicatedStorage:WaitForChild("Food", 30))
    FD.mod = type(FM) == "table" and FM or { List = {}, MAX_CALORIES = 1000 }
end
function FD.cal() return tonumber(lp:GetAttribute("FeederCalories")) or 0 end
function FD.max() return FD.mod.MAX_CALORIES or 1000 end
function FD.feeder()
    local b = G.base()
    for _, c in ipairs(b and b:GetChildren() or {}) do if c.Name:match("^Feeder") then return c end end
end
function FD.held()
    local out, total = {}, 0
    local f = lp:FindFirstChild("Food")
    for _, it in ipairs(FD.mod.List or {}) do
        local n = tonumber(f and f:GetAttribute(it.name)) or 0
        if n > 0 then out[#out + 1] = it total += n * (it.calories or 0) end
    end
    return out, total
end
function FD.buy()
    local rb = G.rebirths()
    local need = FD.max() - FD.cal() - select(2, FD.held())
    local list = {}
    for _, it in ipairs(FD.mod.List or {}) do list[#list + 1] = it end
    table.sort(list, function(a, b) return (a.calories or 0) > (b.calories or 0) end)
    for _, it in ipairs(list) do
        if need <= 0 then break end
        local stock = tonumber(lp:GetAttribute("FoodStock" .. it.name)) or 0
        local free = it.name == FD.mod.FREE_FOOD and lp:GetAttribute("FreeFood")
        if (it.rebirth or 0) <= rb and (stock > 0 or free) and ((it.price or 0) <= G.cash() * 0.25 or free) then
            G.fire("FoodEvent", "Buy", it.name)
            task.wait(0.4)
            need -= it.calories or 0
        end
    end
end
function FD.fill()
    local items = FD.held()
    if #items == 0 or FD.cal() >= FD.max() - 30 then return end
    local fd = FD.feeder()
    if not fd or not M.try() then return end
    local start = hrp() and hrp().CFrame
    S.task = L["Feeding pets"]
    pcall(function()
        M.hop(fd:GetPivot().Position + Vector3.new(0, -1, 3))
        task.wait(0.4)
        local h = hum()
        for _ = 1, 8 do
            if FD.cal() >= FD.max() - 30 then break end
            local tool
            local bp = lp:FindFirstChild("Backpack")
            for _, t in ipairs(bp and bp:GetChildren() or {}) do if t:IsA("Tool") and t:GetAttribute("IsFood") then tool = t break end end
            local held = char() and char():FindFirstChildOfClass("Tool")
            if held and held:GetAttribute("IsFood") then tool = held end
            if not tool then break end
            if tool.Parent ~= char() and h then pcall(function() h:EquipTool(tool) end) task.wait(0.35) end
            G.fire("FoodEvent", "Fill")
            task.wait(0.8)
        end
        if h then pcall(function() h:UnequipTools() end) end
    end)
    if start then M.hop(start.Position) end
    M.free()
end
