local D = {}
F.D = D
function D.disguised() return lp:GetAttribute("Disguised") == true end
function D.pipeAt()
    local b = G.base()
    local pipe = b and b:FindFirstChild("Pipe")
    local inside = pipe and pipe:FindFirstChild("Inside")
    if inside then return inside:IsA("BasePart") and inside.Position or inside:GetPivot().Position end
    return pipe and pipe:GetPivot().Position
end
D.VARS = { "Rainbow", "Diamond", "Gold", "Normal" }
function D.owns(name, var)
    local dis = lp:FindFirstChild("Disguises")
    if G.EM and G.EM.ownsDisguiseVariant then return gcall(G.EM.ownsDisguiseVariant, dis, name, var) == true end
    return false
end
function D.canUse(name, var)
    if not (G.EM and G.EM.canDisguise) then return false end
    if G.EM.available and not gcall(G.EM.available, G.defs[name] or {}) then return false end
    return gcall(G.EM.canDisguise, G.rebirths(), name, var or "Normal") == true
end
function D.payout(name)
    local e = G.defs[name] or {}
    return (G.EM and G.EM.getDisguisePrice and gcall(G.EM.getDisguisePrice, name)) or (e.price or 0) * 10
end
function D.skin(name)
    if on("d_variants") then
        for _, v in ipairs(D.VARS) do if D.owns(name, v) and D.canUse(name, v) then return v end end
    end
    if D.canUse(name, "Normal") then return "Normal" end
    return nil
end
function D.usable()
    local out = {}
    for name in pairs(G.defs) do
        local v = D.skin(name)
        if v then out[#out + 1] = { name = name, var = v, pay = D.payout(name) } end
    end
    table.sort(out, function(a, b) return a.pay > b.pay end)
    return out
end
function D.nextUnlock()
    local best, need, pay
    local rb = G.rebirths()
    for name in pairs(G.defs) do
        if D.owns(name, "Normal") and not D.canUse(name, "Normal") then
            local req = G.EM.getDisguiseRebirths and gcall(G.EM.getDisguiseRebirths, name, "Normal")
            local p = D.payout(name)
            if type(req) == "number" and req < 1e9 and req > rb and (not best or p > pay) then best, need, pay = name, req, p end
        end
    end
    return best, need, pay
end
function D.best()
    local u = D.usable()[1]
    if u then return u.name, u.var, u.pay end
    return nil
end
function D.pick()
    local chosen = val("d_egg", "Best Unlocked")
    if chosen and chosen ~= "Best Unlocked" then
        local v = D.skin(chosen)
        if v then return chosen, v, D.payout(chosen) end
    end
    return D.best()
end
